import React, { cloneElement, useMemo } from 'react';

import { omitTransientProps } from 'utils/emotion';

import type { ChipRootProps } from '../../Chip.types';
import { ChipContext } from '../../hooks';
import { StyledChipRoot } from './ChipRoot.styles';

export const ChipRoot = React.forwardRef<HTMLDivElement, ChipRootProps>(
  (
    {
      children,
      onClick,
      disabled = false,
      selected = false,
      className,
      ...props
    },
    forwardedRef,
  ) => {
    const removable = false;

    const chipChildren = React.Children.map(children, (child, index) => {
      if (!React.isValidElement(child)) {
        return child;
      }

      return cloneElement(child, {
        index,
        ...child.props,
      });
    });

    const contextValue = useMemo(() => ({ disabled }), [disabled]);

    const handleKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
      if ((event.key === 'Enter' || event.key === ' ') && !disabled) {
        onClick?.();
      }
    };

    return (
      <StyledChipRoot
        {...omitTransientProps(props)}
        ref={forwardedRef}
        className={className}
        data-testid="chip-container"
        role="button"
        tabIndex={0}
        $clickable={Boolean(onClick)}
        $disabled={disabled}
        $removable={removable}
        $selected={selected}
        aria-disabled={disabled || !onClick}
        onClick={() => {
          if (!disabled) {
            onClick?.();
          }
        }}
        onKeyDown={handleKeyDown}
      >
        <ChipContext.Provider value={contextValue}>
          {chipChildren}
        </ChipContext.Provider>
      </StyledChipRoot>
    );
  },
);

ChipRoot.displayName = 'Chip.Root';
